export function assertString(value, name) {
  if (typeof value !== "string" || !value.trim()) {
    throw new TypeError(name + " must be a non-empty string");
  }
  return value.trim();
}

export function assertArray(value, name) {
  if (!Array.isArray(value)) {
    throw new TypeError(name + " must be an array");
  }
  return value;
}

export function sha256Text(value) {
  return createHash("sha256").update(String(value)).digest("hex");
}

export function stableClone(value) {
  return structuredClone(value);
}

export function toJson(value) {
  return JSON.stringify(value, null, 2) + "\n";
}

export function parseJson(text) {
  try {
    return JSON.parse(text);
  } catch {
    throw new Error("invalid JSON");
  }
}

export function unique(values) {
  return [...new Set(values)];
}

export function sortById(items) {
  return [...items].sort((a, b) => a.id.localeCompare(b.id));
}

export function requireItem(map, id) {
  const item = map.get(id);
  if (!item) throw new Error("unknown item: " + id);
  return item;
}

export class Registry {
  #items = new Map();

  register(item) {
    if (this.#items.has(item.id)) throw new Error("duplicate id: " + item.id);
    this.#items.set(item.id, Object.freeze(structuredClone(item)));
  }
}

export class Registry {
  get(id) {
    const item = this.#items.get(id);
    return item ? structuredClone(item) : null;
  }
}

export class Registry {
  list() {
    return [...this.#items.values()].map((item) => structuredClone(item));
  }
}

export function normalizePort(value) {
  const port = Number(value);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new TypeError("invalid port");
  }
  return port;
}

export function normalizeBoolean(value, fallback = false) {
  if (value == null) return fallback;
  if (typeof value !== "boolean") throw new TypeError("boolean required");
  return value;
}

export async function readJson(path) {
  const text = await readFile(path, "utf8");
  return JSON.parse(text);
}

export async function writeJson(path, value) {
  await writeFile(path, JSON.stringify(value, null, 2) + "\n");
}

export async function ensureDirectory(path) {
  await mkdir(path, {recursive: true});
}

export function sendJson(res, status, body) {
  res.writeHead(status, {"content-type": "application/json; charset=utf-8"});
  res.end(JSON.stringify(body));
}

export async function readBody(req, limit) {
  let body = "";
  for await (const chunk of req) {
    body += chunk;
    if (Buffer.byteLength(body) > limit) throw new Error("body too large");
  }
  return body ? JSON.parse(body) : {};
}

export function requireBearer(req, expected) {
  const header = req.headers.authorization ?? "";
  if (!header.startsWith("Bearer ")) throw new Error("unauthorized");
  const supplied = header.slice(7);
  if (supplied !== expected) throw new Error("unauthorized");
}

export function routeByPath(req, pathname) {
  return req.method + " " + pathname;
}

export function notFound(res) {
  return sendJson(res, 404, {error: "not_found"});
}

export function badRequest(res, message) {
  return sendJson(res, 400, {error: message});
}

export function ok(res, body) {
  return sendJson(res, 200, body);
}

export function selectActive(items) {
  return items.filter((item) => item.state === "active");
}

export function selectCandidate(items) {
  return items.filter((item) => item.state === "candidate");
}

export function verifySha256(value) {
  return /^[a-f0-9]{64}$/.test(value);
}

export function checkpointRef(hash) {
  if (!verifySha256(hash)) throw new TypeError("invalid checkpoint hash");
  return "sha256:" + hash;
}

export function parseCheckpoint(ref) {
  if (!String(ref).startsWith("sha256:")) throw new Error("invalid checkpoint");
  return String(ref).slice("sha256:".length);
}

export function compareCheckpoint(expected, actual) {
  if (expected !== actual) throw new Error("checkpoint mismatch");
  return true;
}

export function scoreThreshold(value, minimum) {
  return Number.isFinite(value) && value >= minimum;
}

export function enforceMaximum(value, maximum) {
  return Number.isFinite(value) && value <= maximum;
}

export function evaluateGate(metrics) {
  return metrics.accuracy >= 0.8 && metrics.errorRate <= 0.2;
}

export function failClosed(message) {
  const error = new Error(message);
  error.statusCode = 503;
  throw error;
}

export function makeRuntime(infer) {
  if (typeof infer !== "function") throw new TypeError("infer must be a function");
  return Object.freeze({infer});
}

export async function listen(server, port, host = "127.0.0.1") {
  await new Promise((resolve) => server.listen(port, host, resolve));
  return server;
}

export async function close(server) {
  await new Promise((resolve, reject) => {
    server.close((error) => error ? reject(error) : resolve());
  });
}

export function createUrl(path, base = "http://localhost") {
  return new URL(path, base);
}

export function normalizeTask(task) {
  if (typeof task !== "string" || !task) throw new TypeError("task required");
  return task;
}

export function supportsTask(model, task) {
  return Array.isArray(model.tasks) && model.tasks.includes(task);
}

export function chooseByPriority(models) {
  return [...models].sort((a, b) => b.priority - a.priority)[0] ?? null;
}

export function nativeOnly(models) {
  return models.filter((model) => model.origin === "hercules-native");
}

export function requireRuntime(model) {
  if (!model.runtime) throw new Error("runtime required");
  return model.runtime;
}

export function buildManifest({id, task, checkpoint}) {
  return {
    version: "0.1",
    id,
    task,
    checkpoint,
  };
}

export function freezeManifest(manifest) {
  return Object.freeze(structuredClone(manifest));
}

export function tokenCount(text) {
  return String(text).trim().split(/\s+/).filter(Boolean).length;
}

export function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

export function mean(values) {
  if (!values.length) return 0;
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

export function accuracy(correct, total) {
  return total ? correct / total : 0;
}

export function errorRate(correct, total) {
  return total ? 1 - correct / total : 1;
}

test("registry rejects duplicate ids", () => {
  const registry = new Registry();
  registry.register({id: "one"});
  assert.throws(() => registry.register({id: "one"}), /duplicate/);
});

test("checkpoint helper validates sha256", () => {
  const hash = "a".repeat(64);
  assert.equal(checkpointRef(hash), "sha256:" + hash);
});

test("threshold gate passes valid metrics", () => {
  assert.equal(evaluateGate({accuracy: 0.9, errorRate: 0.1}), true);
});

test("threshold gate fails invalid metrics", () => {
  assert.equal(evaluateGate({accuracy: 0.7, errorRate: 0.3}), false);
});

test("native filter removes external models", () => {
  const result = nativeOnly([
    {origin: "external"},
    {origin: "hercules-native"},
  ]);
  assert.equal(result.length, 1);
});

test("task support checks declared tasks", () => {
  assert.equal(supportsTask({tasks: ["code"]}, "code"), true);
  assert.equal(supportsTask({tasks: ["code"]}, "vision"), false);
});

export async function fetchJson(url, options = {}) {
  const response = await fetch(url, options);
  if (!response.ok) throw new Error("request failed: " + response.status);
  return response.json();
}

export function authorization(token) {
  return {authorization: "Bearer " + token};
}

export function jsonHeaders(token) {
  return {
    ...authorization(token),
    "content-type": "application/json",
  };
}

export async function postJson(url, token, body) {
  return fetchJson(url, {
    method: "POST",
    headers: jsonHeaders(token),
    body: JSON.stringify(body),
  });
}

export function env(name, fallback = null) {
  const value = process.env[name];
  return value == null || value === "" ? fallback : value;
}

export function requiredEnv(name) {
  const value = env(name);
  if (!value) throw new Error("missing environment variable: " + name);
  return value;
}

export function redact(value) {
  if (!value) return null;
  return "[redacted]";
}

export function logEvent(event) {
  console.log(JSON.stringify({
    time: new Date().toISOString(),
    ...event,
  }));
}

export function safeError(error) {
  return {
    name: error?.name ?? "Error",
    message: error?.message ?? "unknown error",
  };
}

export function assertOwnerCode(origin) {
  if (origin !== "hercules-native") {
    throw new Error("owner code required");
  }
}

export function candidateEnabled(value) {
  return value === "true";
}

export function productionModel(models, task) {
  return models.find((model) =>
    model.state === "active" && model.tasks.includes(task)
  ) ?? null;
}

export function candidateModel(candidates, id) {
  return candidates.find((model) =>
    model.state === "candidate" && model.id === id
  ) ?? null;
}

export function immutableCopy(value) {
  return Object.freeze(structuredClone(value));
}

export function serializeEvidence(evidence) {
  return JSON.stringify(evidence, null, 2) + "\n";
}

export function verifyEvidence(evidence) {
  if (!evidence?.evaluation?.passed) throw new Error("evaluation failed");
  if (!verifySha256(evidence.checkpointSha256)) throw new Error("invalid hash");
  return true;
}
